+      }
+
+      .page {
+        width: min(1080px, calc(100% - 32px));
+        margin: 0 auto;
+        padding: 48px 0 64px;
+      }
+
+      .hero {
+        display: grid;
+        gap: 16px;
+        padding: 32px;
+        margin-bottom: 24px;
+        border: 1px solid var(--panel-border);
+        border-radius: calc(var(--radius) + 4px);
+        background: var(--panel);
+        backdrop-filter: blur(18px);
+        box-shadow: var(--shadow);
+      }
+
+      .eyebrow {
+        display: inline-flex;
+        align-items: center;
+        gap: 8px;
+        width: fit-content;
+        padding: 8px 12px;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: var(--accent);
+        font-size: 0.875rem;
+        font-weight: 700;
+        letter-spacing: 0.01em;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2.2rem, 4vw, 4rem);
+        line-height: 1.02;
+        letter-spacing: -0.04em;
+      }
+
+      .lead {
+        max-width: 62ch;
+        margin: 0;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.7;
+      }
+
+      .faq-grid {
+        display: grid;
+        gap: 14px;
+      }
+
+      .example {
+        border: 1px solid var(--panel-border);
+        border-radius: 20px;
+        background: rgba(255, 255, 255, 0.88);
+        box-shadow: 0 10px 34px rgba(15, 23, 42, 0.06);
+        overflow: clip;
+      }
+
+      .example details {
+        padding: 0;
+      }
+
+      .example summary {
+        list-style: none;
+        cursor: pointer;
+        padding: 22px 24px;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 16px;
+        font-weight: 700;
+        font-size: 1.03rem;
+        outline: none;
+      }
+
+      .example summary::-webkit-details-marker {
+        display: none;
+      }
+
+      .example summary::after {
+        content: "+";
+        width: 34px;
+        height: 34px;
+        flex: 0 0 34px;
+        display: grid;
+        place-items: center;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: var(--accent);
+        font-size: 1.25rem;
+        line-height: 1;
+      }
+
+      .example details[open] summary::after {
+        content: "–";
+      }
+
+      .example summary:focus-visible {
+        box-shadow: inset 0 0 0 3px rgba(124, 58, 237, 0.22);
+      }
+
+      .details {
+        padding: 0 24px 24px;
+        color: var(--muted);
+        line-height: 1.75;
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      .details p + p {
+        margin-top: 12px;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100% - 20px, 1080px);
+          padding-top: 20px;
+          padding-bottom: 24px;
+        }
+
+        .hero {
+          padding: 24px;
+        }
+
+        .example summary,
+        .details {
+          padding-left: 18px;
+          padding-right: 18px;
+        }
+
+        .details {
+          padding-bottom: 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main id="app"></main>
+
+    <script>
+      const faqs = [
+        {
+          question: "Why do cats purr?",
+          answer: [
+            "Cats purr for comfort, bonding, and sometimes to calm themselves down. A purr can mean a cat is relaxed on your lap, but it can also show up when they are stressed or healing.",
+          ],
+        },
+        {
+          question: "How much sleep do cats need?",
+          answer: [
+            "Most cats sleep 12 to 16 hours a day, and kittens can sleep even more. Their bursty, energy-saving lifestyle is part of what makes them such efficient little hunters.",
+          ],
+        },
+        {
+          question: "Should I worry if my cat kneads blankets?",
+          answer: [
+            "Usually not. Kneading is a comforting behavior that often starts in kittenhood. It can mean your cat feels safe, settled, and very attached to the softest spot in the room.",
+          ],
+        },
+        {
+          question: "Why do cats bring gifts?",
+          answer: [
+            "A cat that drops a toy, leaf, or even a toy mouse at your feet is often showing social bonding or practicing hunting behavior. It's their version of saying, 'I thought of you.'",
+          ],
+        },
+        {
+          question: "What is the best way to keep a cat happy?",
+          answer: [
+            "Give them predictable routines, fresh water, clean litter, vertical spaces, and regular play that lets them chase and pounce. A happy cat usually wants choice, enrichment, and a cozy place to retreat.",
+          ],
+        },
+      ];
+
+      function FAQItem({ question, answer }) {
+        const item = document.createElement("div");
+        item.className = "example";
+
+        const details = document.createElement("details");
+
+        const summary = document.createElement("summary");
+        summary.textContent = question;
+
+        const content = document.createElement("div");
+        content.className = "details";
+        content.innerHTML = answer.map((paragraph) => `<p>${paragraph}</p>`).join("");
+
+        details.append(summary, content);
+        item.append(details);
+        return item;
+      }
+
+      function App() {
+        const root = document.createElement("div");
+        root.className = "page";
+
+        const hero = document.createElement("section");
+        hero.className = "hero";
+        hero.innerHTML = `
+          <div class="eyebrow">Cat FAQ</div>
+          <h1>Everything you wanted to know about cats.</h1>
+          <p class="lead">A clean, expandable FAQ built with a React-style component structure and designed for quick scanning, relaxed reading, and easy interaction.</p>
+        `;
+
+        const list = document.createElement("section");
+        list.className = "faq-grid";
+        faqs.forEach((faq) => list.appendChild(FAQItem(faq)));
+
+        root.append(hero, list);
+        return root;
+      }
+
+      document.getElementById("app").appendChild(App());
+    </script>
+  </body>
+</html>
*** End Patch
