        padding: 32px;
        margin-bottom: 24px;
        border: 1px solid var(--panel-border);
        border-radius: calc(var(--radius) + 4px);
        background: var(--panel);
        backdrop-filter: blur(18px);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        width: fit-content;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.01em;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.2rem, 4vw, 4rem);
        line-height: 1.02;
        letter-spacing: -0.04em;
      }

      .lead {
        max-width: 62ch;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq-grid {
        display: grid;
        gap: 14px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        background: rgba(255, 255, 255, 0.88);
        box-shadow: 0 10px 34px rgba(15, 23, 42, 0.06);
        overflow: clip;
      }

      .example details {
        padding: 0;
      }

