        list-style: none;
        cursor: pointer;
        padding: 22px 24px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        font-weight: 700;
        font-size: 1.03rem;
        outline: none;
      }

      .example summary::-webkit-details-marker {
        display: none;
      }

      .example summary::after {
        content: "+";
        width: 34px;
        height: 34px;
        flex: 0 0 34px;
        display: grid;
        place-items: center;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 1.25rem;
        line-height: 1;
      }

      .example details[open] summary::after {
        content: "–";
      }

      .example summary:focus-visible {
        box-shadow: inset 0 0 0 3px rgba(124, 58, 237, 0.22);
      }

      .details {
        padding: 0 24px 24px;
        color: var(--muted);
        line-height: 1.75;
      }

      .details p {
        margin: 0;
      }

      .details p + p {
        margin-top: 12px;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 1080px);
          padding-top: 20px;
          padding-bottom: 24px;
